def find_function(src,name):
    st=src.find('function '+name)
    if st<0: raise ValueError('no function '+name)
    # find param closing paren
    i=src.find('(',st)
    par=0
    in_str=None; esc=False
    for j in range(i,len(src)):
        ch=src[j]
        if in_str:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==in_str: in_str=None
            continue
        if ch in "'\"`":
            in_str=ch; continue
        if ch=='(':
            par+=1
        elif ch==')':
            par-=1
            if par==0:
                brace=src.find('{',j)
                break
    else:
        raise ValueError('no params end '+name)
    bal=0; in_str=None; esc=False
    for j in range(brace,len(src)):
        ch=src[j]
        if in_str:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==in_str: in_str=None
            continue
        if ch in "'\"`":
            in_str=ch; continue
        if ch=='{': bal+=1
        elif ch=='}':
            bal-=1
            if bal==0:
                return st,j+1,src[st:j+1]
    raise ValueError('no end '+name)

def replace_func(name,new):
    global s
    st,en,old=find_function(s,name)
    s=s[:st]+new+s[en:]
    print('replaced',name,len(old),'->',len(new))

def replace_once(old,new,label):
    global s
    if old not in s:
        raise ValueError('missing '+label)
    s=s.replace(old,new,1)
    print('replaced',label)

